@font-face{font-family:"Manrope";font-style:normal;font-weight:200 800;font-display:swap;src:url(/v9/fonts/manrope-latin-wght-normal.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
/* v12: ortak "şablon" izlerini kaldırır. Renkler logodan: lacivert + turuncu; beyaz zemin; düz, çerçeveli, sıkı. */
:root{--murekkep:#10213d;--metin2:#4a5568;--cizgi:#dde1e8;--zemin:#f4f5f7;--kagit:#fff;--sahne:#fff;--sahne2:#f4f5f7;--cam:#00265b;--filiz:#00265b;--kiremit:#fe6d02;--kiremit-acik:#fff3ea;--cam-acik:#eef2f8;--gol:rgba(0,38,91,.08);--fd:"Manrope",system-ui,sans-serif;--fm:"Manrope",system-ui,sans-serif}
html{scroll-behavior:auto}
body{font-family:"Manrope",system-ui,sans-serif}
h1,h2,h3,h4{font-family:"Manrope",system-ui,sans-serif;font-weight:600;letter-spacing:0;color:var(--murekkep)}
h1,.hero h1{font-size:clamp(32px,4.2vw,52px);line-height:1.12}
h2{font-size:clamp(26px,3vw,36px);line-height:1.2}
h3{font-size:19px;line-height:1.3}
/* üst etiketler: tek renk, düz yazı; nokta, mono, büyük harf yok */
.et,.kr{font:600 14px/1.3 "Manrope",system-ui,sans-serif;letter-spacing:0;text-transform:none;color:#c25400;margin-bottom:10px}
.et:before{display:none !important}
.hero .et,.son .et{color:#c25400}
/* başlık altı çizgisi ve nokta desenleri */
h2:after{display:none !important}
.hero:before,.pb:before,[class*="nokta"]{background-image:none !important}
.hero:before{background:#fff;opacity:1}
.hero,.pb{background:#fff !important}
/* kutular: ince çerçeve, küçük yarıçap, gölgesiz */
.btn,.bt,button.bt,a.bt{border-radius:6px !important;box-shadow:none !important;font-weight:600}
.btn.fil,.btn.dolu,.btn.dolu.kc,.btn.fil.kc,.son .frm button.bt,.son .frm a.bt{background:#00265b !important;border-color:#00265b !important;color:#fff !important}
.btn.fil:hover,.btn.dolu:hover,.son .frm button.bt:hover{background:#fe6d02 !important;border-color:#fe6d02 !important}
.btn.bos{background:#fff !important;border:1.5px solid #00265b !important;color:#00265b !important}
.btn.duz{color:#00265b}
.d,.kp,.sah,.kk,.ek,.kt .kk,figure.tar,.frm,.cd,.pf,.eband{border-radius:6px !important;box-shadow:none !important}
.son .frm{border-radius:8px !important;border:1px solid var(--cizgi) !important}
.son .frm:before{display:none}
.son .frm .alan input,.son .frm .alan select{border-radius:6px;border-width:1px}
/* sahte tarayıcı çerçevesi (üç nokta + yazı): düz çerçeve */
.tar .tb{display:none !important}
.tar,.tar .vp{border-radius:4px !important}
.tar{border:1px solid #cfd5df;box-shadow:none !important;background:#fff}
/* süs: yüzen bildirim kartları, tilt, cam efekti */
.cip,.dnya,#dunya-bolum{display:none !important}
.hero .sahne{display:block}
.hero .sahne .s1,.hero .sahne .s3{display:none !important}
.hero .sahne .s2{position:static !important;transform:none !important;width:100% !important;margin:0 !important}
.hero .sahne{position:relative;height:auto !important}
/* numaralı kart etiketleri */
.dort .d>span,.kp .no,.sah .no,.kpl .no{display:none !important}
/* her karta fade-in kalktı; yalnızca ilk ekran girişi kalır */
.gor,.rz,[data-r]{opacity:1 !important;transform:none !important;transition:none !important}
/* bağlantılar: altı çizili, hoverda renk */
.dort .d:hover,.kp:hover{border-color:#00265b}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #fe6d02;outline-offset:2px}
@media(prefers-reduced-motion:reduce){*{animation:none !important;transition:none !important}}
.hero .sahne .s2 .vp{height:auto !important;aspect-ratio:1400/875;overflow:hidden}
.hero .sahne .s2 .vp img{position:static !important;width:100% !important;height:100% !important;max-width:none;transform:none !important;object-fit:cover}
.hero .g{align-items:center}
.hero .sahne .s2 .vp img{margin:0 !important}
.hero h1 em,.hero h1 em .k>i{background:none !important;-webkit-text-fill-color:#fe6d02 !important;color:#fe6d02 !important;font-style:normal}
.mbar a.f{background:#00265b !important;color:#fff !important}
.bk2 a,.arasik a,.btn.bos2,.flt button,.sek .lst a,.fbant li,[class*="chip"]{border-radius:6px !important}
.kp,.bk a,.slst a,.arasn-k{border-radius:6px !important}
@media(max-width:900px){.hero .sahne{display:block !important;margin-top:24px}.hero .sahne .s2{display:block !important}}
@media(max-width:700px){
footer.alt2 .mag{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-items:stretch}
footer.alt2 .mag .mgb{grid-column:1/-1}
footer.alt2 .mag .rz{display:flex;align-items:center;justify-content:flex-start;gap:8px;padding:0 12px;min-height:48px;margin:0;width:auto}
footer.alt2 .yas{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}
footer.alt2 .yas a{padding:11px 0;border-top:1px solid #cfd8e4}
footer.alt2 .yas a:nth-child(-n+2){border-top:0}
footer.alt2 .alt{display:flex;flex-direction:column;align-items:flex-start;gap:14px;padding-bottom:84px}
footer.alt2 .kart{display:flex;gap:10px}
}
footer.alt2 .kart svg{display:block;overflow:visible;height:32px;width:52px}footer.alt2 .kart{overflow:visible;line-height:0}
.sayi{grid-template-columns:repeat(3,1fr) !important}
.sade .sg{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.sade h2{margin-bottom:14px}
.sade p{color:var(--metin2);max-width:520px}
.sade .kod{background:#0f1a2e;color:#e6ecf5;font:500 13.5px/1.7 ui-monospace,Menlo,Consolas,monospace;padding:18px 20px;border-radius:6px;margin:18px 0;white-space:pre-wrap;overflow-x:auto}
.sade .sssd{border-top:1px solid var(--cizgi);padding:2px 0}
.sade .sssd:last-of-type{border-bottom:1px solid var(--cizgi);margin-bottom:16px}
.sade .sssd summary{cursor:pointer;font-weight:600;padding:14px 0;color:var(--murekkep)}
.sade .sssd p{margin:0 0 14px}
@media(max-width:800px){.sade .sg{grid-template-columns:1fr;gap:36px}.sayi{grid-template-columns:1fr !important}}
#temalar .tkg>*:nth-child(n+10){display:none !important}
#temalar .flt{display:none}
@media(max-width:700px){#temalar .tkg>*:nth-child(n+7){display:none !important}.fbant .fg2>*:nth-child(n+4){display:none}}

/* sektör sayfası zengin bölümler */
#neler-degisir h2,#isinizi-gelistirin h2,#kayit-akisi h2,#sss h2{margin-bottom:22px;max-width:none}
#neler-degisir .lead{max-width:760px;margin-bottom:28px}
#isinizi-gelistirin .sxy{margin-top:22px}
.sxtb thead th{position:static!important}
.sxtb table th:first-child{width:22%}
@media(max-width:700px){.sxtb table th:first-child{width:auto}}
#sektor-tema h2{max-width:none;margin-bottom:14px}#sektor-tema .lead{margin-bottom:22px}
